import { WebSocketServer, WebSocket } from 'ws';
import * as crypto from 'crypto';
import * as http from 'http';

interface TenantSession {
  sessionId: string;
  tenantId: string;
  userId: string;
  permissions: string[];
  createdAt: number;
  lastActivity: number;
}

interface PendingUpgrade {
  sessionId: string;
  tenantId: string;
  timestamp: number;
}

const sessions = new Map<string, TenantSession>();
const wsConnections = new Map<WebSocket, TenantSession>();
const pendingUpgrades = new Map<string, PendingUpgrade>();

function getHmacSecret(): string {
  const secret = process.env.HMAC_SECRET;
  if (!secret) {
    throw new Error('HMAC_SECRET environment variable is not set');
  }
  return secret;
}

function generateSessionId(): string {
  return crypto.randomBytes(32).toString('hex');
}

function validateTenantIsolation(session: TenantSession, targetTenant: string): boolean {
  return session.tenantId === targetTenant;
}

function deriveUpgradeToken(sessionId: string, tenantId: string): string {
  const hmac = crypto.createHmac('sha256', getHmacSecret());
  hmac.update(`${sessionId}:${tenantId}`);
  return hmac.digest('hex');
}

function resolveSessionFromToken(token: string, providedSessionId: string): TenantSession | null {
  const session = sessions.get(providedSessionId);
  if (!session) return null;

  const expectedToken = deriveUpgradeToken(session.sessionId, session.tenantId);
  const providedBuf = Buffer.from(token);
  const expectedBuf = Buffer.from(expectedToken);

  // Guard against timingSafeEqual throwing on unequal-length buffers.
  if (providedBuf.length !== expectedBuf.length) {
    return null;
  }

  if (crypto.timingSafeEqual(providedBuf, expectedBuf)) {
    return session;
  }
  return null;
}

function registerPendingUpgrade(sessionId: string, tenantId: string): string {
  const upgradeId = crypto.randomBytes(16).toString('hex');
  pendingUpgrades.set(upgradeId, {
    sessionId,
    tenantId,
    timestamp: Date.now()
  });
  return upgradeId;
}

function consumePendingUpgrade(upgradeId: string): PendingUpgrade | null {
  const pending = pendingUpgrades.get(upgradeId);
  if (!pending) return null;
  if (Date.now() - pending.timestamp > 30000) {
    pendingUpgrades.delete(upgradeId);
    return null;
  }
  pendingUpgrades.delete(upgradeId);
  return pending;
}

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/session/create') {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      let parsed: any;
      try {
        parsed = JSON.parse(body);
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON body' }));
        return;
      }

      const { tenantId, userId, permissions } = parsed;

      if (typeof tenantId !== 'string' || tenantId.length === 0 ||
          typeof userId !== 'string' || userId.length === 0) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'tenantId and userId are required strings' }));
        return;
      }

      let normalizedPermissions: string[] = ['read'];
      if (permissions !== undefined) {
        if (!Array.isArray(permissions) || !permissions.every(p => typeof p === 'string')) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'permissions must be an array of strings' }));
          return;
        }
        normalizedPermissions = permissions;
      }

      const sessionId = generateSessionId();
      const session: TenantSession = {
        sessionId,
        tenantId,
        userId,
        permissions: normalizedPermissions,
        createdAt: Date.now(),
        lastActivity: Date.now()
      };
      sessions.set(sessionId, session);
      const upgradeId = registerPendingUpgrade(sessionId, tenantId);
      const token = deriveUpgradeToken(sessionId, tenantId);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ sessionId, upgradeId, token }));
    });
  } else {
    res.writeHead(404);
    res.end();
  }
});

const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', (request, socket, head) => {
  const url = new URL(request.url || '', `http://${request.headers.host}`);
  const upgradeId = url.searchParams.get('upgrade_id');
  const token = url.searchParams.get('token');
  const sessionId = url.searchParams.get('session_id');

  if (!upgradeId || !token || !sessionId) {
    socket.destroy();
    return;
  }

  const pending = consumePendingUpgrade(upgradeId);
  if (!pending) {
    socket.destroy();
    return;
  }

  // Resolve session using the client-provided session_id parameter
  const session = resolveSessionFromToken(token, sessionId);
  if (!session) {
    socket.destroy();
    return;
  }

  // Verify tenant matches the pending upgrade's tenant
  if (!validateTenantIsolation(session, pending.tenantId)) {
    socket.destroy();
    return;
  }

  wss.handleUpgrade(request, socket, head, (ws) => {
    wsConnections.set(ws, session);
    ws.on('message', (data) => handleMessage(ws, session, data.toString()));
    ws.on('close', () => wsConnections.delete(ws));
    ws.send(JSON.stringify({ type: 'connected', tenantId: session.tenantId, userId: session.userId }));
  });
});

function handleMessage(ws: WebSocket, session: TenantSession, raw: string): void {
  try {
    const msg = JSON.parse(raw);
    session.lastActivity = Date.now();

    switch (msg.type) {
      case 'query':
        if (!session.permissions.includes('read')) {
          ws.send(JSON.stringify({ type: 'error', message: 'Insufficient permissions' }));
          return;
        }
        ws.send(JSON.stringify({ type: 'result', tenantId: session.tenantId, data: `Data for ${session.tenantId}` }));
        break;
      case 'mutate':
        if (!session.permissions.includes('write')) {
          ws.send(JSON.stringify({ type: 'error', message: 'Insufficient permissions' }));
          return;
        }
        ws.send(JSON.stringify({ type: 'ack', tenantId: session.tenantId }));
        break;
      case 'transfer_session':
        // Session transfer is not supported - reject all attempts
        ws.send(JSON.stringify({ type: 'error', message: 'Session transfer not supported' }));
        break;
    }
  } catch (e) {
    ws.send(JSON.stringify({ type: 'error', message: 'Invalid message format' }));
  }
}

server.listen(8080, () => console.log('Multi-tenant WS server on :8080'));
